      if (v===2) return <g><path d="M10 90 L80 10 M20 95 L90 15" stroke="#3A261F" strokeWidth="4"/><ellipse cx="50" cy="60" rx="6" ry="12" transform="rotate(45 50 60)" fill={c}/><ellipse cx="65" cy="45" rx="6" ry="12" transform="rotate(45 65 45)" fill={a}/></g>; // chopsticks rice
      if (v===3) return <g><ellipse cx="50" cy="58" rx="26" ry="22" fill={c}/><polygon points="28,44 22,20 38,35" fill={c}/><polygon points="72,44 78,20 62,35" fill={c}/><circle cx="38" cy="52" r="5" fill="#1A1A1A"/><circle cx="62" cy="52" r="5" fill="#1A1A1A"/><circle cx="39" cy="51" r="2" fill="#FFF"/><circle cx="63" cy="51" r="2" fill="#FFF"/><ellipse cx="50" cy="60" rx="4" ry="3" fill={a}/><path d="M50 63 Q40 69 32 65 M50 63 Q60 69 68 65" stroke="#1A1A1A" strokeWidth="2" fill="none"/></g>; // cat
