      if (v===3) return <g><path d="M50 20 C60 20 60 35 50 35 M20 70 L50 35 L80 70" stroke={c} strokeWidth="5" fill="none"/><line x1="20" y1="70" x2="80" y2="70" stroke={a} strokeWidth="4"/></g>; // hanger
